    add.s32 %r8, %r7, 4;
    setp.gt.s32 %p0, %r8, %r5;
    @%p0 bra SUM_TAIL;
    cvt.s64.s32 %rd20, %r7;
    shl.b64 %rd20, %rd20, 2;
    add.u64 %rd21, %rd11, %rd20;
    ld.global.v4.f32 {%f12, %f13, %f14, %f15}, [%rd21];
