    sub.f32 %f44, %f32, %f26;
    mul.f32 %f44, %f44, %f27;
    mul.f32 %f44, %f44, %f36;
    add.f32 %f44, %f44, %f40;
    sub.f32 %f45, %f33, %f26;
    mul.f32 %f45, %f45, %f27;
    mul.f32 %f45, %f45, %f37;
    add.f32 %f45, %f45, %f41;
    st.global.v4.f32 [%rd24], {%f42, %f43, %f44, %f45};
    add.s32 %r6, %r6, 1024;
    bra OUT_LOOP;
