    add.u64 %rd22, %rd3, %rd20;
    add.u64 %rd23, %rd4, %rd20;
    add.u64 %rd24, %rd12, %rd20;
    ld.global.f32 %f30, [%rd21];
    ld.global.f32 %f31, [%rd22];
    ld.global.f32 %f32, [%rd23];
    sub.f32 %f33, %f30, %f26;
    mul.f32 %f34, %f33, %f27;
    mul.f32 %f35, %f34, %f31;
